#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <sys/stat.h>

#define VERSION "2025.89"

typedef struct {
    char *banner_file;
    char **key_files;
    int key_file_count;
    char *auth_dir;
    int create_keys;
    int foreground;
    int pass_env;
    int no_motd;
    int no_root;
    char *group_restrict;
    int no_password;
    int no_password_root;
    int allow_blank;
    int two_factor;
    int max_auth_tries;
    int no_local_forward;
    int no_remote_forward;
    int allow_forward_any;
    char *force_command;
    char *listen_ports[10];
    int port_count;
    char *pid_file;
    char *listen_interface;
    int inetd_mode;
    int recv_window;
    int keepalive;
    int idle_timeout;
    int disable_qos;
} Options;

void print_usage() {
    printf("Dropbear server v%s https://matt.ucc.asn.au/dropbear/dropbear.html\n", VERSION);
    printf("Usage: ./executable [options]\n");
    printf("-b bannerfile\tDisplay the contents of bannerfile before user login\n");
    printf("\t\t(default: none)\n");
    printf("-r keyfile      Specify hostkeys (repeatable)\n");
    printf("\t\tdefaults: \n");
    printf("\t\t- rsa /etc/dropbear/dropbear_rsa_host_key\n");
    printf("\t\t- ecdsa /etc/dropbear/dropbear_ecdsa_host_key\n");
    printf("\t\t- ed25519 /etc/dropbear/dropbear_ed25519_host_key\n");
    printf("-D\t\tDirectory containing authorized_keys file\n");
    printf("-R\t\tCreate hostkeys as required\n");
    printf("-F\t\tDon't fork into background\n");
    printf("-e\t\tPass on server process environment to child process\n");
    printf("(Syslog support not compiled in, using stderr)\n");
    printf("-m\t\tDon't display the motd on login\n");
    printf("-w\t\tDisallow root logins\n");
    printf("-G\t\tRestrict logins to members of specified group\n");
    printf("-s\t\tDisable password logins\n");
    printf("-g\t\tDisable password logins for root\n");
    printf("-B\t\tAllow blank password logins\n");
    printf("-t\t\tEnable two-factor authentication (both password and public key required)\n");
    printf("-T\t\tMaximum authentication tries (default 10)\n");
    printf("-j\t\tDisable local port forwarding\n");
    printf("-k\t\tDisable remote port forwarding\n");
    printf("-a\t\tAllow connections to forwarded ports from any host\n");
    printf("-c command\tForce executed command\n");
    printf("-p [address:]port\n");
    printf("\t\tListen on specified tcp port (and optionally address),\n");
    printf("\t\tup to 10 can be specified\n");
    printf("\t\t(default port is 22 if none specified)\n");
    printf("-P PidFile\tCreate pid file PidFile\n");
    printf("\t\t(default /var/run/dropbear.pid)\n");
    printf("-l <interface>\n");
    printf("\t\tinterface to bind on\n");
    printf("-i\t\tStart for inetd\n");
    printf("-W <receive_window_buffer> (default 24576, larger may be faster, max 10MB)\n");
    printf("-K <keepalive>  (0 is never, default 0, in seconds)\n");
    printf("-I <idle_timeout>  (0 is never, default 0, in seconds)\n");
    printf("-z    disable QoS\n");
    printf("-V    Version\n");
}

void print_version() {
    printf("Dropbear v%s\n", VERSION);
}

int main(int argc, char *argv[]) {
    Options opts = {0};
    opts.max_auth_tries = 10;
    opts.recv_window = 24576;
    opts.pid_file = "/var/run/dropbear.pid";

    int i = 1;
    int invalid_option = 0;

    while (i < argc) {
        char *arg = argv[i];

        if (arg[0] != '-' || strlen(arg) < 2) {
            fprintf(stderr, "Invalid argument: %s\n", arg);
            exit(1);
        }

        char opt = arg[1];

        switch(opt) {
            case 'h':
                print_usage();
                return 0;
            case 'V':
                print_version();
                return 0;
            case 'b':
                if (i + 1 < argc) {
                    opts.banner_file = argv[++i];
                }
                break;
            case 'r':
                if (i + 1 < argc) {
                    if (opts.key_file_count < 10) {
                        if (opts.key_files == NULL) {
                            opts.key_files = malloc(10 * sizeof(char*));
                        }
                        opts.key_files[opts.key_file_count++] = argv[++i];
                    }
                }
                break;
            case 'D':
                if (i + 1 < argc) {
                    opts.auth_dir = argv[++i];
                }
                break;
            case 'R':
                opts.create_keys = 1;
                break;
            case 'F':
                opts.foreground = 1;
                break;
            case 'e':
                opts.pass_env = 1;
                break;
            case 'm':
                opts.no_motd = 1;
                break;
            case 'w':
                opts.no_root = 1;
                break;
            case 'G':
                if (i + 1 < argc) {
                    opts.group_restrict = argv[++i];
                }
                break;
            case 's':
                opts.no_password = 1;
                break;
            case 'g':
                opts.no_password_root = 1;
                break;
            case 'B':
                opts.allow_blank = 1;
                break;
            case 't':
                opts.two_factor = 1;
                break;
            case 'T':
                if (i + 1 < argc) {
                    opts.max_auth_tries = atoi(argv[++i]);
                }
                break;
            case 'j':
                opts.no_local_forward = 1;
                break;
            case 'k':
                opts.no_remote_forward = 1;
                break;
            case 'a':
                opts.allow_forward_any = 1;
                break;
            case 'c':
                if (i + 1 < argc) {
                    opts.force_command = argv[++i];
                }
                break;
            case 'p':
                if (i + 1 < argc) {
                    if (opts.port_count < 10) {
                        opts.listen_ports[opts.port_count++] = argv[++i];
                    }
                }
                break;
            case 'P':
                if (i + 1 < argc) {
                    opts.pid_file = argv[++i];
                }
                break;
            case 'l':
                if (i + 1 < argc) {
                    opts.listen_interface = argv[++i];
                }
                break;
            case 'i':
                opts.inetd_mode = 1;
                break;
            case 'W':
                if (i + 1 < argc) {
                    opts.recv_window = atoi(argv[++i]);
                }
                break;
            case 'K':
                if (i + 1 < argc) {
                    opts.keepalive = atoi(argv[++i]);
                }
                break;
            case 'I':
                if (i + 1 < argc) {
                    opts.idle_timeout = atoi(argv[++i]);
                }
                break;
            case 'z':
                opts.disable_qos = 1;
                break;
            default:
                fprintf(stderr, "Invalid option -%c\n", opt);
                invalid_option = 1;
                break;
        }

        i++;
    }

    if (invalid_option) {
        print_usage();
        return 1;
    }

    // Now check for key files
    pid_t pid = getpid();

    // Print log messages for missing key files
    const char *default_keys[] = {
        "/etc/dropbear/dropbear_rsa_host_key",
        "/etc/dropbear/dropbear_ecdsa_host_key",
        "/etc/dropbear/dropbear_ed25519_host_key"
    };

    int has_any_key = 0;

    if (opts.key_file_count == 0) {
        // Check default locations
        for (int j = 0; j < 3; j++) {
            if (access(default_keys[j], F_OK) != -1) {
                has_any_key = 1;
            } else {
                fprintf(stderr, "[%d] ", pid);
                fprintf(stderr, "Failed loading %s\n", default_keys[j]);
            }
        }
    } else {
        // Check specified key files
        for (int j = 0; j < opts.key_file_count; j++) {
            if (access(opts.key_files[j], F_OK) != -1) {
                has_any_key = 1;
            }
        }
    }

    if (opts.banner_file != NULL) {
        if (access(opts.banner_file, F_OK) == -1) {
            fprintf(stderr, "[%d] Error opening banner file '%s'\n", pid, opts.banner_file);
        }
    }

    if (!has_any_key && opts.key_file_count == 0) {
        fprintf(stderr, "[%d] ", pid);
        fprintf(stderr, "Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.\n");
        return 1;
    }

    // If we got here and not in test mode, we'd start the server
    // For now, just exit to indicate we would start
    return 0;
}
EOF

